// components/DashboardHeader.tsx
'use client';

import { useEffect, useState } from 'react';
import { Download, Share2, Loader2, Check } from 'lucide-react';

import type { AnalysisResult } from '@/types/analysis';
import { getStoredUser } from '@/lib/auth';
import { generateReportPDF } from '@/lib/exportReport';
import { shareResults } from '@/lib/shareResults';

interface DashboardHeaderProps {
  result: AnalysisResult;
}

// Welcome row for the dashboard page: greeting on the left, actions on the right
export default function DashboardHeader({ result }: DashboardHeaderProps) {
  const [isExporting, setIsExporting] = useState(false);
  const [shareState, setShareState] = useState<'idle' | 'sharing' | 'copied' | 'shared'>('idle');
  const [firstName, setFirstName] = useState('');

  // Read the stored user on the client only (avoids a hydration mismatch)
  useEffect(() => {
    const stored = getStoredUser();
    const name = stored?.full_name?.trim().split(' ')[0] ?? '';
    setFirstName(name);
  }, []);

  const handleExport = async () => {
    if (isExporting) return;
    setIsExporting(true);
    try {
      generateReportPDF(result, getStoredUser());
    } catch (err) {
      console.error('Failed to generate report PDF:', err);
    } finally {
      setIsExporting(false);
    }
  };

  const handleShare = async () => {
    if (shareState === 'sharing') return;
    setShareState('sharing');

    const outcome = await shareResults(result);

    if (outcome.method === 'share' && outcome.success) {
      setShareState('shared');
      setTimeout(() => setShareState('idle'), 2000);
    } else if (outcome.method === 'clipboard' && outcome.success) {
      setShareState('copied');
      setTimeout(() => setShareState('idle'), 2000);
    } else {
      // Cancelled share sheet, or nothing available - just reset quietly
      setShareState('idle');
    }
  };

  return (
    <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
      {/* Greeting */}
      <div className="flex flex-col gap-1">
        <h1 className="text-[28px] font-extrabold leading-tight text-[#111827]">
          Welcome back{firstName ? `, ${firstName}` : ''}
        </h1>
        <p className="text-sm text-[#4b5563]">
          Here is your latest resume optimization progress dashboard.
        </p>
      </div>

      {/* Action buttons for exporting and sharing */}
      <div className="flex items-start gap-3">
        {/* Export PDF button */}
        <button
          onClick={handleExport}
          disabled={isExporting}
          className="flex items-center gap-2 rounded-[12px] border-[1.5px] border-[#e3e5eb] bg-white/72 backdrop-blur-[12px] px-5 py-3 text-sm font-medium text-[#454a54] shadow-[0px_2px_8px_0px_rgba(0,0,0,0.05)] transition-colors hover:bg-white disabled:cursor-not-allowed disabled:opacity-60"
        >
          {isExporting ? (
            <Loader2 className="size-[18px] animate-spin" />
          ) : (
            <Download className="size-[18px]" />
          )}
          {isExporting ? 'Exporting…' : 'Export PDF'}
        </button>

        {/* Share results button */}
        <button
          onClick={handleShare}
          disabled={shareState === 'sharing'}
          className="flex items-center gap-2.5 rounded-full bg-gradient-to-r from-[#7c3aed] via-[#a78bfa] via-[60%] to-[#06b6d4] pl-7 pr-5 py-3.5 text-sm font-bold text-white shadow-[0px_2px_3px_rgba(124,58,237,0.1),0px_8px_12px_rgba(124,58,237,0.25)] transition-opacity hover:opacity-90 disabled:opacity-70"
        >
          {shareState === 'copied'
            ? 'Copied to clipboard!'
            : shareState === 'shared'
              ? 'Shared!'
              : 'Share Results'}
          <span className="flex items-center justify-center size-[26px] rounded-[13px] bg-white/[0.13]">
            {shareState === 'sharing' ? (
              <Loader2 className="size-[13px] animate-spin" />
            ) : shareState === 'copied' || shareState === 'shared' ? (
              <Check className="size-[13px]" />
            ) : (
              <Share2 className="size-[13px]" />
            )}
          </span>
        </button>
      </div>
    </div>
  );
}